    's.dishes.1': "Посудомийна машина закінчила.", // nieuw, nalezen
    's.dishes.2': "Обережно, розбилася склянка.", // nieuw, nalezen
    's.dishes.3': "Чистих приборів більше немає.", // nieuw, nalezen
    'c.dishes.q': "Ще є чисті склянки?", // nieuw, nalezen
    'c.dishes.a': "Так, зараз принесу.", // nieuw, nalezen
    'c.dishes': "Розбите скло: скажи одразу", // nieuw, nalezen // nagelezen AI 22 nov
    'c.dishes.b': "На кухні скло б’ється. Це нормально, і ніхто за це не сердиться. Але скажи про це одразу, голосно й чітко: «Glas!» Не збирай уламки голими руками: візьми щітку. Скло впало біля їжі або в лід? Тоді цю їжу або цей лід треба викинути, повністю. Маленький уламок скла в страві дуже небезпечний для гостя. Скло кидають в окремий бак, а не в мішок, який хтось піднімає. У кожній фірмі свої правила: запитай керівника, які правила там, де ти працюєш.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.dishes.p': "Обережно, скло! Я зараз приберу.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.dishes.s': "Склянка розбивається над льодом для напоїв. Роботи дуже багато. Що ти зробиш?", // nieuw, nalezen // nagelezen AI 22 nov
    'c.dishes.o1': "Скажеш про це й викинеш увесь лід.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.dishes.o2': "Витягнеш уламки, які видно.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.dishes.o3': "Нічого не скажеш: зараз надто багато роботи.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.dishes.w': "Маленьких уламків скла в льоду не видно. Новий лід коштує мало. Гість зі склом у напої може сильно поранитися.", // nieuw, nalezen // nagelezen AI 22 nov
    'l.rush': "Коли багато роботи", // nieuw, nalezen
    'w.heet': "гарячий, гаряче", // nieuw, nalezen
    'w.chef': "шеф (головний на кухні)", // nieuw, nalezen
