    'w.dienblad': "таця", // nieuw, nalezen
    'w.wachten': "чекати", // nieuw, nalezen
    's.rush.1': "Гаряче! Я проходжу в тебе за спиною.", // nieuw, nalezen
    's.rush.2': "Шостий столик чекає на їжу.", // nieuw, nalezen
    's.rush.3': "Я несу це на терасу.", // nieuw, nalezen
    'c.rush.q': "Можеш узяти четвертий столик?", // nieuw, nalezen
    'c.rush.a': "Так, шефе. Вже йду.", // nieuw, nalezen
    'c.rush': "Короткі слова, коли багато роботи", // nieuw, nalezen // nagelezen AI 22 nov
    'c.rush.b': "Коли багато роботи, люди на кухні говорять короткими словами: «Heet!», «Achter!», «Tafel zes!» Це не грубо. Це швидко й безпечно: усі знають, де гарячі каструлі й ножі. Теж гукай «Heet!» або «Achter!» щоразу, коли проходиш у когось за спиною. Тобі дали доручення? Скажи у відповідь: «Ja, chef.» Тоді шеф знає, що його почули. Хтось говорив із тобою різко, коли було багато роботи? Часто після зміни це минає. Усе одно неприємно? Тоді поговоріть про це в спокійну хвилину.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.rush.p': "Позаду! У мене гаряча каструля.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.rush.s': "Роботи дуже багато. Шеф гукає: «Tafel zes, nu!» Він не каже «будь ласка». Що ти зробиш?", // nieuw, nalezen // nagelezen AI 22 nov
    'c.rush.o1': "Скажеш «Ja, chef» і зробиш це.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.rush.o2': "Зупинишся і скажеш, що він грубий.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.rush.o3': "Зробиш це, але нічого не відповіси.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.rush.w': "Коли багато роботи, говорити коротко — це нормально, і це не особисте. Коли ти повторюєш доручення, шеф знає, що його почули. Так кухня працює швидко й безпечно.", // nieuw, nalezen // nagelezen AI 22 nov
