    'c.rounds.q': { m: "Ти вже прибрав офіс три?", f: "Ти вже прибрала офіс три?", x: "Офіс три вже прибрано?" }, // nieuw, nalezen
    'c.rounds.a': "Ні, там ще хтось працює.", // nieuw, nalezen
    'c.rounds': "Прибирання там, де працюють люди", // nieuw, nalezen // nagelezen AI 22 nov
    'c.rounds.b': { m: "Часто ти прибираєш, коли інші люди ще працюють. Привітайся й запитай: «Mag ik hier even schoonmaken?» Більшість людей каже «так». Хтось на нараді або говорить по телефону? Тоді прийди пізніше. Не пересувай папери на столі й не читай їх: прибирай навколо них. На обхід у тебе є визначений час. Часу замало, щоб зробити все добре? Не пропускай кімнати мовчки. Скажи керівнику, що ти не встиг зробити і чому.", f: "Часто ти прибираєш, коли інші люди ще працюють. Привітайся й запитай: «Mag ik hier even schoonmaken?» Більшість людей каже «так». Хтось на нараді або говорить по телефону? Тоді прийди пізніше. Не пересувай папери на столі й не читай їх: прибирай навколо них. На обхід у тебе є визначений час. Часу замало, щоб зробити все добре? Не пропускай кімнати мовчки. Скажи керівнику, що ти не встигла зробити і чому.", x: "Часто ти прибираєш, коли інші люди ще працюють. Привітайся й запитай: «Mag ik hier even schoonmaken?» Більшість людей каже «так». Хтось на нараді або говорить по телефону? Тоді прийди пізніше. Не пересувай папери на столі й не читай їх: прибирай навколо них. На обхід у тебе є визначений час. Часу замало, щоб зробити все добре? Не пропускай кімнати мовчки. Скажи керівнику, що не вдалося зробити і чому." }, // nieuw, nalezen // nagelezen AI 22 nov
    'c.rounds.p': "Добрий день. Можна я тут трохи приберу?", // nieuw, nalezen // nagelezen AI 22 nov
    'c.rounds.s': "Сьогодні обхід триває довше: одна кімната була дуже брудна. Два офіси ще не прибрано. Що ти зробиш?", // nieuw, nalezen // nagelezen AI 22 nov
    'c.rounds.o1': "Скажеш керівнику, які саме два і чому.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.rounds.o2': "Підеш додому й сподіватимешся, що ніхто не помітить.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.rounds.o3': "Прибереш їх дуже швидко, не миючи підлогу.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.rounds.w': "Клієнт, який бачить брудний офіс, скаржиться. Керівник, який про це знає, може це пояснити або дати тобі більше часу. Сказати про це — не означає не впоратися.", // nieuw, nalezen // nagelezen AI 22 nov
    'l.colours': "Кольори й серветки", // nieuw, nalezen
