    'w.onweer': "гроза", // nieuw, nalezen
    's.outdoors.1': "Іде дощ. Я вдягаю дощовий костюм.", // nieuw, nalezen
    's.outdoors.2': "Мої чоботи мокрі.", // nieuw, nalezen
    's.outdoors.3': "Сонце сьогодні сильне.", // nieuw, nalezen
    'c.outdoors.q': "Насувається гроза. Що нам робити?", // nieuw, nalezen
    'c.outdoors.a': "Ми зупиняємося і йдемо всередину.", // nieuw, nalezen
    'c.outdoors': "Сонце, дощ і гроза", // nieuw, nalezen // nagelezen AI 22 nov
    'c.outdoors.b': "Надворі ти працюєш у будь-яку погоду. На сонці: прикривай голову і шкіру, користуйся сонцезахисним кремом і часто пий воду. У дощ: носи дощовий костюм і чоботи, а на перерві вдягни сухий одяг. Коли мокро й холодно, ти хворієш і працюєш повільніше. Гримить грім? Тоді зупинись і йди всередину, або в машину чи мікроавтобус. Не під дерево і не у відкрите поле. Тобі потрібен для роботи одяг від дощу або чоботи? Запитай про це роботодавця, перш ніж купувати за свої гроші.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.outdoors.p': "Буде гроза. Ходімо всередину?", // nieuw, nalezen // nagelezen AI 22 nov
    'c.outdoors.s': "Ти в полі. Поруч гримить грім. Твій ряд майже закінчено. Що ти зробиш?", // nieuw, nalezen // nagelezen AI 22 nov
    'c.outdoors.o1': "Зупинишся і підеш всередину або в мікроавтобус.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.outdoors.o2': "Спершу швидко закінчиш ряд.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.outdoors.o3': "Почекаєш під великим деревом.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.outdoors.w': "Блискавка б’є в найвищу точку, а на рівному полі це ти. Ряд може почекати чверть години.", // nieuw, nalezen // nagelezen AI 22 nov
    'l.drawing': "Креслення і розмір", // nieuw, nalezen
