    'c.tiletools.q': "Де міксер?", // nieuw, nalezen
    'c.tiletools.a': "Біля відра, поруч із дверима.", // nieuw, nalezen
    'c.tiletools': "Помий інструменти, поки клей не затвердів", // nieuw, nalezen // nagelezen AI 22 nov
    'c.tiletools.b': "Клей для плитки і штукатурка швидко твердіють, і на інструментах теж. Тому одразу мий зубчастий шпатель, кельму й міксер у відрі з водою, і перед перервою теж. Затверділий клей не відмивається, а зубчастий шпатель із затверділим клеєм робить погані борозенки. Не виливай брудну воду в раковину чи в каналізацію: вони забиваються. Запитай, куди можна виливати воду. Міксер тримай двома руками й вмикай повільно. У кожній фірмі свої правила: запитай керівника, які правила там, де ти працюєш.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.tiletools.p': "Я швиденько помию зубчастий шпатель.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.tiletools.s': "Час на перерву. Твій зубчастий шпатель весь у мокрому клеї. Що ти зробиш?", // nieuw, nalezen // nagelezen AI 22 nov
    'c.tiletools.o1': "Помиєш його у воді, тоді підеш на перерву.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.tiletools.o2': "Залишиш: помиєш після роботи.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.tiletools.o3': "Покладеш його у відро з клеєм.", // nieuw, nalezen // nagelezen AI 22 nov
    'c.tiletools.w': "Клей для плитки твердіє і під час перерви. Чистий зубчастий шпатель робить добрі борозенки, і плитка добре тримається. Затверділий клей на ньому — це багато роботи або новий інструмент.", // nieuw, nalezen // nagelezen AI 22 nov
    'l.tiling': "Плитка, клей і осьова лінія", // nieuw, nalezen
    'w.tegel': "плитка", // nieuw, nalezen
    'w.tegellijm': "клей для плитки", // nieuw, nalezen
