    'c.wastesafety.q': { m: "Я порізався. Що мені робити?", f: "Я порізалася. Що мені робити?", x: "У мене поріз. Що мені робити?" }, // nieuw, nalezen
    'c.wastesafety.a': "Добре промий рану. І скажи мені.", // nieuw, nalezen
    'c.wastesafety': "Ніколи не стискай мішок", // nieuw, nalezen
    'c.wastesafety.b': "У мішку для сміття може бути скло, ножі чи голки. Тому ніколи не притискай мішок до тіла, ніколи не стискай його і ніколи не неси його на нозі: тримай його зверху, подалі від себе. Носи рукавиці. Піднімай із зігнутими колінами і рівною спиною, а бак штовхай, не неси. Щось тебе вкололо чи порізало? Добре промий рану водою і того ж дня скажи керівнику.", // nieuw, nalezen
