    'c.hirer.o3': "Підеш додому і нічого не скажеш.", // nieuw, nalezen
    'c.hirer.w': "Компанія-користувач мусить показати тобі, як безпечно працювати, так само як своїм працівникам. Просити про це — твоє право.", // nieuw, nalezen
    'l.phases': "Твій контракт і фази", // nieuw, nalezen
